"""Regenerate exact-version, all-wheel hash locks from official PyPI records."""

import importlib.metadata
import json
from pathlib import Path
from urllib.request import urlopen

PACKAGES = ("cffi", "cryptography", "pycparser", "securesystemslib", "tuf", "urllib3")


def main():
    root = Path(__file__).resolve().parent.parent
    records = []
    lines = ["# Exact versions and official PyPI SHA-256 hashes; all platforms.",
             "# Generated by scripts/lock_dependencies.py in the validated environment."]
    for name in PACKAGES:
        version = importlib.metadata.version(name)
        url = f"https://pypi.org/pypi/{name}/{version}/json"
        with urlopen(url, timeout=30) as response:
            record = json.load(response)
        files = [dict(filename=item["filename"], size=item["size"],
                      sha256=item["digests"]["sha256"], url=item["url"])
                 for item in record["urls"] if item["packagetype"] == "bdist_wheel"]
        if not files:
            raise RuntimeError(f"No wheel for {name}")
        hashes = sorted({item["sha256"] for item in files})
        lines.append(f"{name}=={version} \\")
        lines.extend("    --hash=sha256:" + value + (" \\" if index < len(hashes)-1 else "")
                     for index, value in enumerate(hashes))
        records.append(dict(name=name, version=version, source=url,
            license=record["info"].get("license_expression") or record["info"].get("license"),
            files=files))
    (root / "requirements-lock.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")
    (root / "docs" / "DEPENDENCY_PROVENANCE.json").write_text(
        json.dumps(records, indent=2), encoding="utf-8")
    print(f"Locked {len(records)} dependencies with official artifact hashes")


if __name__ == "__main__":
    main()
